function renderCommunity(){const tabs=[['ind','Indicações'],['grp','Grupos'],['biz','Negócios']];let h=`<div class="page-head"><div><h1>Comunidade</h1><p>O que a comunidade sabe fica disponível para quem chegar depois.</p></div>${readonly()?'':communityTab==='grp'?btn('Criar grupo','create-group','','tonal','group_add'):communityTab==='ind'?btn('Perguntar','ask','','tonal','edit_square'):''}</div>${readonlyHtml()}<div class="tabs-wrap"><md-tabs id="community-tabs">${tabs.map(([v,t])=>`<md-primary-tab ${communityTab===v?'active':''} data-action="community-tab" data-value="${v}">${t}</md-primary-tab>`).join('')}</md-tabs></div>`;
 if(communityTab==='grp')return h+renderGroupsTab();
 if(communityTab==='biz')return h+`${pagedHtml('community-biz',state.city,cityBiz().filter(x=>!isSpon(x)).sort((a,b)=>b.recN-a.recN),businessCard,{noun:'negócios'})}${btn('Ver todos os negócios','businesses','','text')}`;
 const solved=cityAsks().filter(q=>q.status==='ok').length;h+=`<div class="context-strip" style="margin-top:0">${icon('history_edu')}<span><b>${solved} indicações resolvidas</b><br>Busque uma resposta antes de perguntar.</span></div>${filterChips([['help','Para ajudar'],['ok','Resolvidas'],['mine','Minhas']],questionFilter,'question-filter')}`;
 const list=cityAsks().filter(q=>questionFilter==='mine'?q.mine:questionFilter==='help'?q.status==='open'&&!q.mine:q.status===questionFilter).sort((a,b)=>questionFilter==='help'?(a.answers.length-b.answers.length||b.createdAt-a.createdAt):b.createdAt-a.createdAt);
 if(questionFilter==='help'&&list.length)h+=`<p class="form-note g-help-note">${icon('volunteer_activism')}Perguntas sem resposta aparecem primeiro. Responder leva um minuto.</p>`;
 return h+(list.length?pagedHtml('asks',`${state.city}|${questionFilter}`,list,questionRow,{noun:'perguntas',art:'as',wrap:'list',end:askEndHtml()}):empty(questionFilter==='help'?'Ninguém esperando resposta':'Nenhuma pergunta por aqui','Você pode buscar uma indicação ou iniciar uma nova pergunta.','forum',readonly()?'':'ask',readonly()?'':'Pedir indicação'));
}
